import {depotEase} from './depot-motion.js?v=depot-v17';
export function titleEase(q,mode){q=Math.max(0,Math.min(1,q));return mode==='linear'?q:mode==='in'?q*q:mode==='out'?1-(1-q)**3:mode==='snap'?+(q>=1):depotEase(q)}
export function titleGlyphPose(index,q,f){const stagger=f.depotTitleStagger??.025,delay=(f.depotTitleMode==='scatter'?index*7%9:index)*stagger,r=titleEase((q-delay)/Math.max(.05,1-delay),f.depotTitleEasing),d=(1-r)*(f.depotTitleDistance??300),mode=f.depotTitleMode||'scatter';return {r,x:mode==='left'?-d:mode==='right'?d:mode==='scatter'?Math.sin(index*5.7)*d:0,y:mode==='up'?d:mode==='down'?-d:mode==='scatter'?Math.cos(index*4.3)*d*.73:0,scale:mode==='scale'?1+(1-r)*1.7:1,rotation:mode==='scatter'?(1-r)*Math.sin(index*3)*.24:0,alpha:mode==='type'?+(r>.05):r}}
export function paintDepotTitle(c,t,f){const start=f.depotTitleStart??((f.depotDuration??58)-6.2),age=t-start;if(age<0)return;const mode=f.depotTransitionMode||'flash',bloom=mode==='flash'||mode==='iris'?Math.exp(-Math.pow((age-.55)/.22,2)):0;if(bloom>.002){c.save();c.globalCompositeOperation='screen';c.globalAlpha=bloom*.88;const light=c.createRadialGradient(500,240,10,500,240,650);light.addColorStop(0,'#fffdf6');light.addColorStop(.45,'#fff9edb0');light.addColorStop(1,'#fff0');c.fillStyle=light;c.fillRect(0,0,960,540);c.restore()}const q=Math.max(0,Math.min(1,(age-.65)/(f.depotTitleTime??2.4)));if(!q)return;c.save();c.textAlign='center';c.textBaseline='middle';c.globalAlpha=depotEase((age-.7)/.8);c.font=`400 ${f.depotTitleSubtitleSize??27}px Arial`;c.fillStyle='#f7f8fa';c.shadowColor='#f2f8ff66';c.shadowBlur=7;c.fillText(f.depotTitleLine??'THE INSANE TRUE STORY OF',480,(f.depotTitleY??300)-70);c.shadowBlur=0;const parts=[[f.depotTitleLeft??'ADIDAS',f.depotTitleLeftColor??'#25a8df'],[f.depotTitleJoin??' AND ','#fafafa'],[f.depotTitleRight??'PUMA',f.depotTitleRightColor??'#f34630']];c.font=`800 ${f.depotTitleSize??62}px Arial`;const widths=parts.map(([word])=>c.measureText(word).width),total=widths.reduce((a,b)=>a+b,0);let cursor=480-total/2,index=0;c.textAlign='left';for(const [word,color]of parts)for(const letter of word){const width=c.measureText(letter).width,p=titleGlyphPose(index,q,f);c.save();c.translate(cursor+p.x,(f.depotTitleY??300)+p.y);c.rotate(p.rotation);c.scale(p.scale,p.scale);c.globalAlpha=p.alpha;c.fillStyle=color;c.filter=`blur(${(1-p.r)*7}px)`;c.fillText(letter,0,0);c.restore();cursor+=width;index++}c.restore()}
